7	/**
8	 * @fileoverview Defines the core configuration interfaces and types for the agent architecture.
9	 */
10	
11	import type { Content, FunctionDeclaration } from '@google/genai';
12	import type { AnyDeclarativeTool } from '../tools/tools.js';
13	import { type z } from 'zod';
14	import type { ModelConfig } from '../services/modelConfigService.js';
15	import type { AnySchema } from 'ajv';
16	import type { A2AAuthConfig } from './auth-provider/types.js';
17	
18	/**
19	 * Describes the possible termination modes for an agent.
20	 */
21	export enum AgentTerminateMode {
22	  ERROR = 'ERROR',
23	  TIMEOUT = 'TIMEOUT',
24	  GOAL = 'GOAL',
25	  MAX_TURNS = 'MAX_TURNS',
26	  ABORTED = 'ABORTED',
27	  ERROR_NO_COMPLETE_TASK_CALL = 'ERROR_NO_COMPLETE_TASK_CALL',
28	}
29	
30	/**
31	 * Represents the output structure of an agent's execution.
32	 */
33	export interface OutputObject {
34	  result: string;
35	  terminate_reason: AgentTerminateMode;
36	}
37	
38	/**
39	 * The default query string provided to an agent as input.
40	 */
41	export const DEFAULT_QUERY_STRING = 'Get Started!';
42	
43	/**
44	 * The default maximum number of conversational turns for an agent.
45	 */
46	export const DEFAULT_MAX_TURNS = 15;
47	
48	/**
49	 * The default maximum execution time for an agent in minutes.
50	 */
51	export const DEFAULT_MAX_TIME_MINUTES = 5;
52	
53	/**
54	 * Represents the validated input parameters passed to an agent upon invocation.
55	 * Used primarily for templating the system prompt. (Replaces ContextState)
56	 */
57	export type AgentInputs = Record<string, unknown>;
58	
59	/**
60	 * Simplified input structure for Remote Agents, which consumes a single string query.
61	 */
62	export type RemoteAgentInputs = { query: string };
63	
64	/**
65	 * Structured events emitted during subagent execution for user observability.
66	 */
67	export interface SubagentActivityEvent {
68	  isSubagentActivityEvent: true;
69	  agentName: string;
70	  type: 'TOOL_CALL_START' | 'TOOL_CALL_END' | 'THOUGHT_CHUNK' | 'ERROR';
71	  data: Record<string, unknown>;
72	}
73	
74	/**
75	 * The base definition for an agent.
76	 * @template TOutput The specific Zod schema for the agent's final output object.
77	 */
78	export interface BaseAgentDefinition<
79	  TOutput extends z.ZodTypeAny = z.ZodUnknown,
80	> {
81	  /** Unique identifier for the agent. */
82	  name: string;
83	  displayName?: string;
84	  description: string;
85	  experimental?: boolean;
86	  inputConfig: InputConfig;
87	  outputConfig?: OutputConfig<TOutput>;
88	  metadata?: {
89	    hash?: string;
90	    filePath?: string;
91	  };
92	}
93	
94	export interface LocalAgentDefinition<
95	  TOutput extends z.ZodTypeAny = z.ZodUnknown,
96	> extends BaseAgentDefinition<TOutput> {
97	  kind: 'local';
98	
99	  // Local agent required configs
100	  promptConfig: PromptConfig;
101	  modelConfig: ModelConfig;
102	  runConfig: RunConfig;
103	
104	  // Optional configs
105	  toolConfig?: ToolConfig;
106	
107	  /**
108	   * An optional function to process the raw output from the agent's final tool
109	   * call into a string format.
110	   *
111	   * @param output The raw output value from the `complete_task` tool, now strongly typed with TOutput.
112	   * @returns A string representation of the final output.
113	   */
114	  processOutput?: (output: z.infer<TOutput>) => string;
115	}
116	
117	export interface RemoteAgentDefinition<
118	  TOutput extends z.ZodTypeAny = z.ZodUnknown,
119	> extends BaseAgentDefinition<TOutput> {
120	  kind: 'remote';
121	  agentCardUrl: string;
122	  /**
123	   * Optional authentication configuration for the remote agent.
124	   * If not specified, the agent will try to use defaults based on the AgentCard's
125	   * security requirements.
126	   */
127	  auth?: A2AAuthConfig;
128	}
129	
130	export type AgentDefinition<TOutput extends z.ZodTypeAny = z.ZodUnknown> =
131	  | LocalAgentDefinition<TOutput>
132	  | RemoteAgentDefinition<TOutput>;
133	
134	/**
135	 * Configures the initial prompt for the agent.
136	 */
137	export interface PromptConfig {
138	  /**
139	   * A single system prompt string. Supports templating using `${input_name}` syntax.
140	   */
141	  systemPrompt?: string;
142	  /**
143	   * An array of user/model content pairs for few-shot prompting.
144	   */
145	  initialMessages?: Content[];
146	
147	  /**
148	   * The specific task or question to trigger the agent's execution loop.
149	   * This is sent as the first user message, distinct from the systemPrompt (identity/rules)
150	   * and initialMessages (history/few-shots). Supports templating.
151	   * If not provided, a generic "Get Started!" message is used.
152	   */
153	  query?: string;
154	}
155	
156	/**
157	 * Configures the tools available to the agent during its execution.
158	 */
159	export interface ToolConfig {
160	  tools: Array<string | FunctionDeclaration | AnyDeclarativeTool>;
161	}
162	
163	/**
164	 * Configures the expected inputs (parameters) for the agent.
165	 */
166	export interface InputConfig {
167	  inputSchema: AnySchema;
168	}
169	
170	/**
171	 * Configures the expected outputs for the agent.
172	 */
173	export interface OutputConfig<T extends z.ZodTypeAny> {
174	  /**
175	   * The name of the final result parameter. This will be the name of the
176	   * argument in the `submit_final_output` tool (e.g., "report", "answer").
177	   */
178	  outputName: string;
179	  /**
180	   * A description of the expected output. This will be used as the description
181	   * for the tool argument.
182	   */
183	  description: string;
184	  /**
185	   * Optional JSON schema for the output. If provided, it will be used as the
186	   * schema for the tool's argument, allowing for structured output enforcement.
187	   * Defaults to { type: 'string' }.
188	   */
189	  schema: T;
190	}
191	
192	/**
193	 * Configures the execution environment and constraints for the agent.
194	 */
195	export interface RunConfig {
196	  /**
197	   * The maximum execution time for the agent in minutes.
198	   * If not specified, defaults to DEFAULT_MAX_TIME_MINUTES (5).
199	   */
200	  maxTimeMinutes?: number;
201	  /**
202	   * The maximum number of conversational turns.
203	   * If not specified, defaults to DEFAULT_MAX_TURNS (15).
204	   */
205	  maxTurns?: number;
206	}
