/**
 * @fileoverview Manages the lifecycle of the browser used by the experimental
 * browser agent. It connects to `chrome-devtools-mcp` over stdio using the raw
 * MCP SDK Client (intentionally NOT the shared McpClientManager), discovers the
 * available browser tools, and proxies tool calls.
 */

import * as os from 'node:os';
import * as path from 'node:path';
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
import type { Tool as McpTool } from '@modelcontextprotocol/sdk/types.js';
import type { Config } from '../../config/config.js';

/**
 * The name reported to the MCP server when constructing the raw SDK Client.
 */
export const BROWSER_MCP_CLIENT_NAME = 'gemini-cli-browser-agent';

/**
 * The logical server name used for policy/confirmation for browser tools.
 */
export const BROWSER_MCP_SERVER_NAME = 'browser-agent';

/**
 * The pinned version of the chrome-devtools-mcp package spawned via npx.
 */
export const CHROME_DEVTOOLS_MCP_VERSION = '0.6.0';

/**
 * The name of the persistent browser profile directory used in the default
 * (persistent) session mode.
 */
const PERSISTENT_PROFILE_DIR_NAME = 'cli-browser-profile';

/**
 * Timeout (ms) used when connecting to the MCP server / launching Chrome.
 */
const CONNECT_TIMEOUT_MSEC = 60_000;

/**
 * A single content item from an MCP tool call, normalized to the fields the
 * browser agent cares about.
 */
export interface McpContentItem {
  type: 'text' | 'image';
  text?: string;
  data?: string;
  mimeType?: string;
}

/**
 * The normalized result of an MCP tool call.
 */
export interface McpToolCallResult {
  content?: McpContentItem[];
  isError?: boolean;
}

interface RawContentItem {
  type?: string;
  text?: string;
  data?: string;
  mimeType?: string;
}

function normalizeContentItem(item: RawContentItem): McpContentItem {
  return {
    type: item.type === 'image' ? 'image' : 'text',
    text: item.text,
    data: item.data,
    mimeType: item.mimeType,
  };
}

export class BrowserManager {
  private client?: Client;
  private transport?: StdioClientTransport;
  private connected = false;
  private discoveredTools?: McpTool[];

  constructor(private readonly config: Config) {}

  /**
   * Returns the cached raw MCP SDK Client, constructing it on first access.
   * The Client constructor is only ever called once.
   */
  async getRawMcpClient(): Promise<Client> {
    if (!this.client) {
      this.client = new Client({
        name: BROWSER_MCP_CLIENT_NAME,
        version: '1.0.0',
      });
    }
    return this.client;
  }

  /**
   * Ensures a live connection to the chrome-devtools-mcp server, spawning it
   * via `npx` if necessary. Idempotent: repeated calls after a successful
   * connection are no-ops.
   */
  async ensureConnection(): Promise<void> {
    if (this.connected) {
      return;
    }

    const { customConfig } = this.config.getBrowserAgentConfig();
    const sessionMode = customConfig.sessionMode ?? 'persistent';

    const args: string[] = [
      '-y',
      `chrome-devtools-mcp@${CHROME_DEVTOOLS_MCP_VERSION}`,
      '--experimental-vision',
    ];

    if (customConfig.headless) {
      args.push('--headless');
    }

    if (sessionMode === 'existing') {
      args.push('--autoConnect');
    } else if (sessionMode === 'isolated') {
      args.push('--isolated');
      if (customConfig.profilePath) {
        args.push('--userDataDir', customConfig.profilePath);
      }
    } else {
      // persistent (default)
      const profilePath =
        customConfig.profilePath ??
        path.join(os.tmpdir(), PERSISTENT_PROFILE_DIR_NAME);
      args.push('--userDataDir', profilePath);
    }

    const client = await this.getRawMcpClient();
    const transport = new StdioClientTransport({
      command: 'npx',
      args,
      stderr: 'pipe',
    });
    this.transport = transport;

    try {
      await client.connect(transport, { timeout: CONNECT_TIMEOUT_MSEC });
      this.connected = true;
    } catch (error) {
      this.connected = false;
      const message = error instanceof Error ? error.message : String(error);
      throw this.buildConnectionError(sessionMode, message);
    }
  }

  private buildConnectionError(sessionMode: string, message: string): Error {
    if (sessionMode === 'existing') {
      return new Error(
        `Failed to connect to existing Chrome instance. Ensure Chrome is ` +
          `running with remote debugging enabled (launch Chrome with ` +
          `--remote-debugging-port=9222) and that the target is visible at ` +
          `chrome://inspect/#remote-debugging.\nOriginal error: ${message}`,
      );
    }

    if (/already running|already in use|singletonlock|processsingleton/i.test(
      message,
    )) {
      return new Error(
        `Chrome is already running with this profile. Close all Chrome ` +
          `windows using this profile and try again. Set sessionMode to ` +
          `"isolated" to launch with a fresh temporary profile instead.\n` +
          `Original error: ${message}`,
      );
    }

    if (/timed out|timeout|etimedout/i.test(message)) {
      return new Error(
        `Timed out launching the browser. Chrome is not installed or could ` +
          `not be started. Install Google Chrome and ensure it is available ` +
          `on your PATH.\nOriginal error: ${message}`,
      );
    }

    return new Error(
      `Failed to start the browser agent (sessionMode: ${sessionMode}). ` +
        `Original error: ${message}`,
    );
  }

  /**
   * Discovers the tools exposed by the MCP server. Results are cached.
   */
  async getDiscoveredTools(): Promise<McpTool[]> {
    await this.ensureConnection();
    if (this.discoveredTools) {
      return this.discoveredTools;
    }
    const client = await this.getRawMcpClient();
    const response = await client.listTools({});
    this.discoveredTools = response.tools ?? [];
    return this.discoveredTools;
  }

  /**
   * Calls an MCP tool and returns the normalized result.
   */
  async callTool(
    toolName: string,
    args: Record<string, unknown>,
    signal?: AbortSignal,
  ): Promise<McpToolCallResult> {
    await this.ensureConnection();
    const client = await this.getRawMcpClient();

    const raw = (await client.callTool(
      { name: toolName, arguments: args },
      undefined,
      signal ? { signal } : undefined,
    )) as { content?: RawContentItem[]; isError?: boolean };

    const content = Array.isArray(raw?.content)
      ? raw.content.map(normalizeContentItem)
      : [];

    return {
      content,
      isError: raw?.isError === true,
    };
  }

  /**
   * Closes the MCP client connection and the underlying transport.
   */
  async close(): Promise<void> {
    const client = this.client;
    const transport = this.transport;

    this.connected = false;
    this.discoveredTools = undefined;

    if (transport) {
      await transport.close();
    }
    if (client) {
      await client.close();
    }
  }
}
