type ToolParams = Record<string, unknown>;

/**
 * The name of the always-included composite typing tool.
 */
export const TYPE_TEXT_TOOL_NAME = 'type_text';

function extractTextContent(content?: McpContentItem[]): string {
  if (!Array.isArray(content)) {
    return '';
  }
  return content
    .filter(
      (item): item is McpContentItem =>
        item.type === 'text' && typeof item.text === 'string',
    )
    .map((item) => item.text)
    .join('\n');
}

/**
 * Base invocation shared by MCP-wrapped tools and the composite type_text tool.
 * Provides MCP-style confirmation and policy behavior scoped to the
 * `browser-agent` server.
 */
abstract class BrowserToolInvocation extends BaseToolInvocation<
  ToolParams,
  ToolResult
> {
  constructor(
    protected readonly browserManager: BrowserManager,
    protected readonly mcpToolName: string,
    params: ToolParams,
    messageBus: MessageBus,
  ) {
    super(params, messageBus, mcpToolName, mcpToolName, BROWSER_MCP_SERVER_NAME);
  }

  getDescription(): string {
    return safeJsonStringify(this.params);
  }

  protected override getPolicyUpdateOptions(
    _outcome: ToolConfirmationOutcome,
  ): PolicyUpdateOptions | undefined {
    return { mcpName: BROWSER_MCP_SERVER_NAME };
  }

  protected override async getConfirmationDetails(
    _abortSignal: AbortSignal,
  ): Promise<ToolCallConfirmationDetails | false> {
    const confirmationDetails: ToolMcpConfirmationDetails = {
      type: 'mcp',
      title: 'Confirm Browser Tool Execution',
      serverName: BROWSER_MCP_SERVER_NAME,
      toolName: this.mcpToolName,
      toolDisplayName: this.mcpToolName,
      toolArgs: this.params,
      onConfirm: async (outcome: ToolConfirmationOutcome) => {
        await this.publishPolicyUpdate(outcome);
      },
    };
    return confirmationDetails;
  }

  protected async callBrowserTool(
    toolName: string,
    args: ToolParams,
    signal: AbortSignal,
  ): Promise<ToolResult> {
    const result = await this.browserManager.callTool(toolName, args, signal);
    const textContent = extractTextContent(result.content);

    if (result.isError) {
      return {
        llmContent: `Error: ${textContent}`,
        returnDisplay: textContent,
        error: { message: textContent },
      };
    }

    return {
      llmContent: textContent,
      returnDisplay: textContent,
      error: undefined,
    };
  }
}

class BrowserMcpToolInvocation extends BrowserToolInvocation {
  async execute(signal: AbortSignal): Promise<ToolResult> {
    try {
      return await this.callBrowserTool(this.mcpToolName, this.params, signal);
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      return {
        llmContent: `Error: ${errorMsg}`,
        returnDisplay: errorMsg,
        error: { message: errorMsg },
      };
    }
  }
}

