/**
 * @fileoverview Declarative tool that captures a screenshot of the current page
 * and sends it to a configured visual model for analysis.
 */

import type { GenerateContentResponse, Part } from '@google/genai';
import {
  BaseDeclarativeTool,
  BaseToolInvocation,
  Kind,
  type ToolInvocation,
  type ToolResult,
} from '../../tools/tools.js';
import type { MessageBus } from '../../confirmation-bus/message-bus.js';
import type { Config } from '../../config/config.js';
import { LlmRole } from '../../telemetry/llmRole.js';
import type { BrowserManager } from './browserManager.js';

/**
 * The canonical name of the visual analysis tool.
 */
export const ANALYZE_SCREENSHOT_TOOL_NAME = 'analyze_screenshot';

interface AnalyzeScreenshotParams {
  instruction: string;
}

const ANALYZE_SCREENSHOT_SCHEMA = {
  type: 'object',
  properties: {
    instruction: {
      type: 'string',
      description:
        'What to look for or identify in the screenshot (e.g. "find the ' +
        'coordinates of the Sign In button").',
    },
  },
  required: ['instruction'],
};

class AnalyzeScreenshotInvocation extends BaseToolInvocation<
  AnalyzeScreenshotParams,
  ToolResult
> {
  constructor(
    private readonly browserManager: BrowserManager,
    private readonly config: Config,
    params: AnalyzeScreenshotParams,
    messageBus: MessageBus,
  ) {
    super(
      params,
      messageBus,
      ANALYZE_SCREENSHOT_TOOL_NAME,
      ANALYZE_SCREENSHOT_TOOL_NAME,
    );
  }

  getDescription(): string {
    return `Analyze a screenshot: ${this.params.instruction}`;
  }

  async execute(signal: AbortSignal): Promise<ToolResult> {
    // 1. Capture a screenshot from the browser.
    const shot = await this.browserManager.callTool(
      'take_screenshot',
      {},
      signal,
    );

    const image = shot.content?.find(
      (item) => item.type === 'image' && typeof item.data === 'string',
    );

    if (!image || !image.data) {
      const message =
        'Failed to capture screenshot: the browser did not return any image ' +
        'content.';
      return {
        llmContent: message,
        returnDisplay: message,
        error: { message },
      };
    }

    // 2. Send the screenshot to the visual model.
    const visualModel =
      this.config.getBrowserAgentConfig().customConfig.visualModel;

    try {
      const response = await this.config.getContentGenerator().generateContent(
        {
          model: visualModel!,
          contents: [
            {
              role: 'user',
              parts: [
                {
                  inlineData: {
                    mimeType: image.mimeType ?? 'image/png',
                    data: image.data,
                  },
                },
                { text: this.params.instruction },
              ],
            },
          ],
        },
        `browser-agent-analyze-screenshot-${this.config.getSessionId()}`,
        LlmRole.SUBAGENT,
      );

      const analysis = extractText(response);
      if (!analysis) {
        const message =
          'Visual model returned no analysis for the screenshot.';
        return {
          llmContent: message,
          returnDisplay: message,
          error: { message },
        };
      }

      const llmContent = `Visual Analysis Result:\n\n${analysis}`;
      return {
        llmContent,
        returnDisplay: llmContent,
        error: undefined,
      };
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      if (/404|403|not found|permission/i.test(errorMsg)) {
        const message =
          `Visual analysis model is not available (model: ` +
          `${visualModel ?? 'unknown'}). ${errorMsg}`;
        return {
          llmContent: message,
          returnDisplay: message,
          error: { message },
        };
      }

      const message = `Visual analysis failed: ${errorMsg}`;
      return {
        llmContent: message,
        returnDisplay: message,
        error: { message },
      };
    }
  }
}

function extractText(response: GenerateContentResponse): string {
  const parts: Part[] | undefined = response?.candidates?.[0]?.content?.parts;
  if (!parts || parts.length === 0) {
    return '';
  }
  return parts
    .map((part) => (typeof part.text === 'string' ? part.text : ''))
    .join('')
    .trim();
}

class AnalyzeScreenshotTool extends BaseDeclarativeTool<
  AnalyzeScreenshotParams,
  ToolResult
> {
  constructor(
    private readonly browserManager: BrowserManager,
    private readonly config: Config,
    messageBus: MessageBus,
  ) {
    super(
      ANALYZE_SCREENSHOT_TOOL_NAME,
      ANALYZE_SCREENSHOT_TOOL_NAME,
      'Capture a screenshot of the current page and analyze it with a visual ' +
        'model to identify elements, read content, or locate coordinates.',
      Kind.Read,
      ANALYZE_SCREENSHOT_SCHEMA,
      messageBus,
      /* isOutputMarkdown */ true,
      /* canUpdateOutput */ false,
    );
  }

  protected createInvocation(
    params: AnalyzeScreenshotParams,
    messageBus: MessageBus,
  ): ToolInvocation<AnalyzeScreenshotParams, ToolResult> {
    return new AnalyzeScreenshotInvocation(
      this.browserManager,
      this.config,
      params,
      messageBus,
    );
  }
}

/**
 * Creates the `analyze_screenshot` declarative tool.
 */
export function createAnalyzeScreenshotTool(
  browserManager: BrowserManager,
  config: Config,
  messageBus: MessageBus,
): AnalyzeScreenshotTool {
  return new AnalyzeScreenshotTool(browserManager, config, messageBus);
}
