/**
 * Creates the browser agent definition together with the BrowserManager that
 * owns the underlying browser connection.
 *
 * The caller is responsible for calling {@link cleanupBrowserAgent} on the
 * returned manager when the agent is done.
 */
export async function createBrowserAgentDefinition(
  config: Config,
  messageBus: MessageBus,
  printOutput?: (msg: string) => void,
): Promise<{
  definition: LocalAgentDefinition<typeof BROWSER_AGENT_OUTPUT_SCHEMA>;
  browserManager: BrowserManager;
}> {
  const browserManager = new BrowserManager(config);
  await browserManager.ensureConnection();

  printOutput?.('Browser agent connected.');

  const { model, customConfig } = config.getBrowserAgentConfig();
  const visionEnabled = Boolean(customConfig.visualModel);

  const tools = await createMcpDeclarativeTools(browserManager, messageBus);
  if (visionEnabled) {
    tools.push(createAnalyzeScreenshotTool(browserManager, config, messageBus));
  }

  const systemPrompt = buildBrowserSystemPrompt(visionEnabled);

  const definition: LocalAgentDefinition<typeof BROWSER_AGENT_OUTPUT_SCHEMA> = {
    name: BROWSER_AGENT_NAME,
    kind: 'local',
    displayName: 'Browser Agent',
    description:
      'Autonomous agent that operates a real web browser to accomplish tasks ' +
      'such as navigating sites, extracting information, and interacting with ' +
      'web applications.',
    inputConfig: {
      inputSchema: {
        type: 'object',
        properties: {
          task: {
            type: 'string',
            description:
              'A detailed description of the browsing task to accomplish, ' +
              'including any starting URL and the desired outcome.',
          },
        },
        required: ['task'],
      },
    },
    outputConfig: {
      outputName: 'result',
      description:
        'A summary of what was accomplished in the browser, including any ' +
        'information gathered or a clear explanation if the task was blocked.',
      schema: BROWSER_AGENT_OUTPUT_SCHEMA,
    },
    promptConfig: {
      systemPrompt,
      query: 'Your task:\n${task}',
    },
    modelConfig: {
      model: model ?? config.getModel(),
    },
    runConfig: {
      maxTimeMinutes: 10,
      maxTurns: 25,
    },
    toolConfig: {
      tools,
    },
  };

  return { definition, browserManager };
}

/**
 * Closes the browser manager, swallowing any error so cleanup always resolves.
 */
export async function cleanupBrowserAgent(
  browserManager: BrowserManager,
): Promise<void> {
  try {
    await browserManager.close();
  } catch {
    // Best-effort cleanup: never surface close() errors.
  }
}
